    @Override protected void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("masari_data",MODE_PRIVATE);todayKey=dateKey(Calendar.getInstance());taskFilter=prefs.getString("v17_filter",prefs.getString("v16_filter","الكل"));applyPalette();setupDomains();migrateV17();autoBackup();syncCredits();render();}
