    private void applyPalette(){boolean dark=prefs!=null&&prefs.getBoolean("dark_mode",false);if(dark){BG=Color.rgb(17,24,29);CARD=Color.rgb(27,36,42);TEXT=Color.rgb(239,244,246);MUTED=Color.rgb(164,178,186);BORDER=Color.rgb(47,60,68);TRACK=Color.rgb(40,50,56);getWindow().setStatusBarColor(Color.rgb(17,24,29));getWindow().getDecorView().setSystemUiVisibility(0);}else{BG=Color.rgb(249,250,251);CARD=Color.WHITE;TEXT=Color.rgb(24,31,39);MUTED=Color.rgb(107,116,126);BORDER=Color.rgb(231,234,237);TRACK=Color.rgb(239,242,244);getWindow().setStatusBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);}getWindow().setNavigationBarColor(NAVY);}
    private void setupDomains(){domainColors.clear();domainColors.put("القرآن",GREEN);domainColors.put("الطب والقبول",CYAN);domainColors.put("الإنجليزية",BLUE);domainColors.put("العمل والدخل",ORANGE);domainColors.put("الصحة",RED);domainColors.put("المعرفة والقراءة",PURPLE);domainColors.put("التواصل",TEAL);domainColors.put("الأسرة",PINK);domainColors.put("الدين والمسجد",Color.rgb(64,133,83));domainColors.put("الانضباط",Color.rgb(102,113,126));domainColors.put("الراحة",REST);}

    private void migrateV17(){if(prefs.getBoolean("v17_migrated",false))return;SharedPreferences.Editor e=prefs.edit();int old=prefs.getInt("reward_domain_الإنجليزية والقبول",0);if(old>0&&prefs.getInt("reward_domain_الإنجليزية",0)==0)e.putInt("reward_domain_الإنجليزية",old);int oldQ=prefs.getInt("reward_domain_القرآن والحفظ",0);if(oldQ>0&&prefs.getInt("reward_domain_القرآن",0)==0)e.putInt("reward_domain_القرآن",oldQ);e.putBoolean("v17_migrated",true).apply();}

    private void render(){handler.removeCallbacks(timerTick);if(currentScroll!=null)scrollY.put(tab,currentScroll.getScrollY());LinearLayout shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);shell.setBackgroundColor(BG);FrameLayout body=new FrameLayout(this);shell.addView(body,new LinearLayout.LayoutParams(-1,0,1));View page;switch(tab){case"tasks":page=tasksPage();break;case"stats":page=statsPage();break;case"rewards":page=rewardsPage();break;case"weekly":page=weeklyReviewPage();break;case"monthly":page=monthlyReviewPage();break;case"goals":page=goalsPage();break;case"later":page=laterPage();break;case"more":page=morePage();break;default:page=homePage();}body.addView(page,new FrameLayout.LayoutParams(-1,-1));shell.addView(bottomNav(),new LinearLayout.LayoutParams(-1,dp(72)));setContentView(shell);if(page instanceof ScrollView){currentScroll=(ScrollView)page;int y=scrollY.containsKey(tab)?scrollY.get(tab):0;currentScroll.post(()->currentScroll.scrollTo(0,y));}else currentScroll=null;}

    private View homePage(){ScrollView s=scroll();LinearLayout r=root(s);r.addView(topBar("مساري","bell","menu"));addGreeting(r);addDayBanner(r);addNowCard(r);if(!isFriday(Calendar.getInstance()))addMatchCard(r);if(!isFriday(Calendar.getInstance()))addEmergencyMini(r);addProgressCard(r);addGoalCard(r);if(isFriday(Calendar.getInstance()))addFridayIdeas(r);else{r.addView(sectionHeader("جدول اليوم","عرض الكل",v->{tab="tasks";render();}));for(Task t:homeTasks())addTaskCard(r,t,true);if(shouldOfferRescue()&&!rescueActiveToday())addRescueCard(r);}addStreakCard(r);LinearLayout q=new LinearLayout(this);q.setOrientation(LinearLayout.HORIZONTAL);q.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);q.setPadding(0,dp(7),0,0);q.addView(quickTile("الطب","medicine",CYAN),weightSmall());q.addView(quickTile("القرآن","quran",GREEN),weightSmall());q.addView(quickTile("English","headphones",BLUE),weightSmall());q.addView(quickTile("العمل","briefcase",ORANGE),weightSmall());r.addView(q);if(undoTaskId!=null&&System.currentTimeMillis()<undoUntil)addUndoBar(r);gap(r,18);return s;}

    private void addGreeting(LinearLayout r){LinearLayout hello=row();hello.addView(new ProfileAvatar(this),new LinearLayout.LayoutParams(dp(54),dp(54)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(9),0,0,0);tx.addView(text("مرحبًا، ميمون",18,TEXT,true));String sub=isFriday(Calendar.getInstance())?"الجمعة راحة بلا دين مهام أو شعور بالذنب.":isThursday(Calendar.getInstance())?"الخميس للمراجعة الكبرى وتقييم الأسبوع.":"القرآن والقبول الطبي أولًا، ثم الإنجليزية والعمل.";tx.addView(text(sub,9,MUTED,false));hello.addView(tx,new LinearLayout.LayoutParams(0,-2,1));hello.addView(center("👋",19,TEXT,false),new LinearLayout.LayoutParams(dp(36),dp(36)));add(r,hello,5);}

    private void addDayBanner(LinearLayout r){Calendar c=Calendar.getInstance();String mode=dayMode(c);if("normal".equals(mode))return;String icon,title,sub;int col;if("friday".equals(mode)){icon="rest";title="جمعة الراحة";sub="لا نسبة مطلوبة، ولا سلسلة تنكسر، ولا مهام تُرحّل للسبت.";col=REST;}else if("thursday".equals(mode)){icon="review";title="الخميس — إغلاق الأسبوع";sub="مراجعة القرآن والمجالات، ثم تقييم واضح وقرار واحد فقط للأسبوع القادم.";col=PURPLE;}else if("rescue".equals(mode)){icon="rescue";title="نسخة الإنقاذ";sub="قرآن صغير + طب صغير + إغلاق اليوم. لا تحاول تعويض اليوم كله.";col=ORANGE;}else{icon="shield";title="وضع ظرف طارئ";sub=emergencyLabel(emergencyFor(c))+" — تم تخفيف اليوم دون احتسابه كفشل.";col=BLUE;}LinearLayout b=card();b.setPadding(dp(10),dp(9),dp(10),dp(9));add(r,b,7);LinearLayout rr=row();rr.addView(new AppIconView(this,icon,col),new LinearLayout.LayoutParams(dp(43),dp(43)));LinearLayout t=new LinearLayout(this);t.setOrientation(LinearLayout.VERTICAL);t.setPadding(dp(8),0,0,0);t.addView(text(title,12,TEXT,true));t.addView(text(sub,8,MUTED,false));rr.addView(t,new LinearLayout.LayoutParams(0,-2,1));b.addView(rr);if(isThursday(c))b.setOnClickListener(v->{tab="weekly";render();});}

    private void addNowCard(LinearLayout r){LinearLayout b=card();b.setPadding(dp(10),dp(9),dp(10),dp(9));add(r,b,8);LinearLayout head=row();head.addView(text("الآن",13,TEXT,true),new LinearLayout.LayoutParams(0,-2,1));if(timerTaskId()!=null)head.addView(pill("مؤقت يعمل",GREEN));b.addView(head);if(isFriday(Calendar.getInstance())){b.addView(emptyState("rest","اليوم لك","استرح، زر أهلك، العب، اقرأ أو اخرج. الراحة اليوم جزء من الخطة."));return;}Task cur=currentTask();if(cur==null){b.addView(emptyState("check","لا توجد مهمة الآن","عندما يحين التالي سيظهر هنا مباشرة."));return;}LinearLayout rr=row();int c=colorFor(cur.domain);rr.addView(new AppIconView(this,cur.icon,c),new LinearLayout.LayoutParams(dp(46),dp(46)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(8),0,dp(5),0);tx.addView(text(cur.title,12,TEXT,true));tx.addView(text(time(displayStart(cur))+" – "+time(displayEnd(cur))+"  •  "+cur.tier,8,MUTED,false));tx.addView(text("يخدم: "+cur.goal,8,c,true));rr.addView(tx,new LinearLayout.LayoutParams(0,-2,1));Button go=smallButton(timerMatches(cur)?"فتح":"ابدأ",GREEN);rr.addView(go,new LinearLayout.LayoutParams(dp(62),dp(34)));go.setOnClickListener(v->showTaskDialog(cur));b.addView(rr);if(timerMatches(cur)){TextView tm=center(timerLabel(),18,GREEN,true);tm.setPadding(0,dp(7),0,0);b.addView(tm);}Task nx=nextTaskAfter(cur);if(nx!=null){TextView nt=text("بعدها: "+nx.title,8,MUTED,false);nt.setPadding(0,dp(6),0,0);b.addView(nt);}}

    private void addMatchCard(LinearLayout r){String used=matchDateThisWeek();boolean usedThis=!used.isEmpty();LinearLayout b=card();b.setPadding(dp(10),dp(8),dp(10),dp(8));add(r,b,7);LinearLayout rr=row();rr.addView(new AppIconView(this,"football",usedThis?MUTED:GREEN),new LinearLayout.LayoutParams(dp(42),dp(42)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(8),0,0,0);tx.addView(text("بطاقة المباراة الأسبوعية",11,TEXT,true));tx.addView(text(usedThis?"استخدمت يوم "+dayNameFromKey(used)+" — تتجدد السبت.":"١ متبقية: تستبدل كل ما بعد العشاء بالمباراة.",8,MUTED,false));rr.addView(tx,new LinearLayout.LayoutParams(0,-2,1));TextView btn=pill(usedThis?"مستخدمة":"استخدم الليلة",usedThis?MUTED:GREEN);rr.addView(btn);b.addView(rr);if(!usedThis){b.setOnClickListener(v->confirmMatchUse());btn.setOnClickListener(v->confirmMatchUse());}}
    private void confirmMatchUse(){List<Task>removed=new ArrayList<>();for(Task t:tasksTodayBase())if(t.start>=1230)removed.add(t);StringBuilder m=new StringBuilder("سيتم استبدال مهام ما بعد العشاء بالمباراة:\n");for(Task t:removed)m.append("• ").append(t.title).append("\n");m.append("\nالبطاقة مرة واحدة فقط حتى السبت القادم.");new AlertDialog.Builder(this).setTitle("استخدام بطاقة المباراة؟").setMessage(m.toString()).setNegativeButton("إلغاء",null).setPositiveButton("استخدمها",(d,w)->{prefs.edit().putString("match_week_"+weekId(Calendar.getInstance()),todayKey).apply();Toast.makeText(this,"ليلة المباراة مفعلة",Toast.LENGTH_SHORT).show();render();}).show();}

    private void addEmergencyMini(LinearLayout r){String e=emergencyFor(Calendar.getInstance());LinearLayout b=card();b.setPadding(dp(9),dp(7),dp(9),dp(7));add(r,b,6);LinearLayout rr=row();rr.addView(new MiniIconView(this,"shield",e.isEmpty()?MUTED:BLUE),new LinearLayout.LayoutParams(dp(24),dp(24)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(7),0,0,0);tx.addView(text(e.isEmpty()?"هل تغيّر يومك؟":"الوضع الحالي: "+emergencyLabel(e),10,TEXT,true));tx.addView(text(e.isEmpty()?"مرض، التزام عائلي، نوم متأخر أو انقطاع إنترنت — عدّل اليوم بضغطة.":"الهدف خفّف تلقائيًا؛ يمكنك إلغاء الوضع من هنا.",8,MUTED,false));rr.addView(tx,new LinearLayout.LayoutParams(0,-2,1));rr.addView(pill(e.isEmpty()?"الظروف":"تعديل",e.isEmpty()?MUTED:BLUE));b.addView(rr);b.setOnClickListener(v->showEmergencyDialog());}

    private void addProgressCard(LinearLayout r){LinearLayout pc=card();pc.setPadding(dp(11),dp(9),dp(11),dp(10));add(r,pc,8);LinearLayout ph=row();ph.addView(text("تقدمك",13,TEXT,true),new LinearLayout.LayoutParams(0,-2,1));ph.addView(text(isFriday(Calendar.getInstance())?"راحة":ar(dayRate(Calendar.getInstance()))+"٪",9,isFriday(Calendar.getInstance())?REST:GREEN,true));pc.addView(ph);LinearLayout rings=new LinearLayout(this);rings.setOrientation(LinearLayout.HORIZONTAL);rings.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);addRing(rings,"اليوم",dayRate(Calendar.getInstance()),isFriday(Calendar.getInstance())?REST:GREEN,55);addRing(rings,"الأسبوع",weekRate(),BLUE,55);addRing(rings,"الشهر",monthRate(),PURPLE,55);addRing(rings,"السنة",yearRate(),GOLD,55);pc.addView(rings);String g=isFriday(Calendar.getInstance())?"الجمعة خارج حساب التقصير.":dayRate(Calendar.getInstance())>=80?"✓ اليوم ناجح — لا تضف شيئًا جديدًا.":"ركز على التالي فقط، لا على كل القائمة.";pc.addView(center(g,9,MUTED,false));}

    private void addGoalCard(LinearLayout r){if(isFriday(Calendar.getInstance()))return;LinearLayout goal=card();goal.setPadding(dp(11),dp(10),dp(11),dp(9));add(r,goal,8);boolean th=isThursday(Calendar.getInstance());LinearLayout gh=row();gh.addView(new AppIconView(this,th?"review":"target",th?PURPLE:GREEN),new LinearLayout.LayoutParams(dp(43),dp(43)));LinearLayout gt=new LinearLayout(this);gt.setOrientation(LinearLayout.VERTICAL);gt.setPadding(dp(8),0,0,0);gt.addView(text(th?"هدف الخميس":"هدف اليوم",15,TEXT,true));gt.addView(text(th?"قرآن + مراجعات المجالات + تقييم الأسبوع":"٤ من ٥ مؤشرات = يوم ناجح، والخامس يوم متكامل",9,MUTED,false));gh.addView(gt,new LinearLayout.LayoutParams(0,-2,1));goal.addView(gh);LinearLayout cr=new LinearLayout(this);cr.setOrientation(LinearLayout.HORIZONTAL);cr.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);cr.setPadding(0,dp(8),0,dp(6));if(th){addCoreDot(cr,"قرآن",hasStatus("thu_quran"),GREEN);addCoreDot(cr,"طب",hasStatus("thu_medicine"),CYAN);addCoreDot(cr,"English",hasStatus("thu_english"),BLUE);addCoreDot(cr,"عمل",hasStatus("thu_work"),ORANGE);addCoreDot(cr,"تقييم",hasStatus("thu_review"),PURPLE);goal.addView(cr);goal.addView(progress(thursdayCoreDone(),5,PURPLE,5));}else{addCoreDot(cr,"قرآن",coreDone("quran"),GREEN);addCoreDot(cr,"طب",coreDone("medicine"),CYAN);addCoreDot(cr,"English",coreDone("english"),BLUE);addCoreDot(cr,"عمل",coreDone("work"),ORANGE);addCoreDot(cr,"انضباط",coreDone("close"),Color.rgb(105,116,126));goal.addView(cr);goal.addView(progress(coreDoneToday(),5,GREEN,5));if(coreDoneToday()>=4)goal.addView(center(coreDoneToday()==5?"✓ يوم متكامل + رصيد إضافي":"✓ اليوم ناجح",9,GREEN,true));}}

    private void addFridayIdeas(LinearLayout r){r.addView(sectionHeader("اقتراحات اختيارية","بلا نقاط",null));String[][] xs={{"لعبة قصصية","gamepad"},{"حلقة أنمي أو مانغا","play"},{"زيارة أو جلسة عائلية","family"},{"قراءة حرة","book"},{"خروج أو مشي هادئ","walk"},{"نوم وراحة","rest"}};LinearLayout grid=new LinearLayout(this);grid.setOrientation(LinearLayout.VERTICAL);for(int i=0;i<xs.length;i+=2){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);for(int j=0;j<2&&i+j<xs.length;j++)row.addView(fridayTile(xs[i+j][0],xs[i+j][1]),new LinearLayout.LayoutParams(0,dp(88),1));grid.addView(row);}r.addView(grid);LinearLayout note=card();note.setPadding(dp(10),dp(9),dp(10),dp(9));add(r,note,8);note.addView(text("قاعدة الجمعة",11,REST,true));note.addView(text("لا تعويض لمهام الأسبوع، ولا فتح قائمة إنجاز سرية. إذا فعلت شيئًا مفيدًا فهو زائد جميل وليس واجبًا.",9,MUTED,false));}
    private View fridayTile(String title,String icon){LinearLayout x=card();x.setGravity(Gravity.CENTER);x.setPadding(dp(4),dp(6),dp(4),dp(5));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(84),1);p.setMargins(dp(3),dp(3),dp(3),dp(3));x.setLayoutParams(p);x.addView(new AppIconView(this,icon,REST),new LinearLayout.LayoutParams(dp(36),dp(36)));x.addView(center(title,8,TEXT,true));return x;}

    private View tasksPage(){ScrollView s=scroll();LinearLayout r=root(s);r.addView(topBar("المهام","more","filter"));r.addView(weekStrip());if(isFriday(Calendar.getInstance())){addDayBanner(r);addFridayIdeas(r);gap(r,18);return s;}HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout chips=new LinearLayout(this);chips.setOrientation(LinearLayout.HORIZONTAL);chips.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);String[] fs={"الكل","أساسي","قرآن","طب","إنجليزية","عمل","صحة","أسرة","LeapAhead"};for(String f:fs){TextView c=filterChip(f,f.equals(taskFilter));chips.addView(c);c.setOnClickListener(v->{taskFilter=f;prefs.edit().putString("v17_filter",f).apply();render();});}hs.addView(chips);r.addView(hs,new LinearLayout.LayoutParams(-1,dp(44)));Task now=currentTask();r.addView(sectionHeader("الآن","",null));if(now!=null&&matches(now))addTaskCard(r,now,false);else addEmptyCard(r,"لا توجد مهمة حالية","ستظهر المهمة التي يحين وقتها هنا.");List<Task>next=nextTasks(3);r.addView(sectionHeader("التالي",ar(next.size()),null));for(Task t:next)if(matches(t))addTaskCard(r,t,false);List<Task>later=laterTasks();r.addView(sectionHeader("لاحقًا اليوم",laterExpanded?"إخفاء":"عرض "+ar(later.size()),v->{laterExpanded=!laterExpanded;render();}));if(laterExpanded)for(Task t:later)if(matches(t))addTaskCard(r,t,false);else if(!later.isEmpty())addCollapsedPreview(r,later);List<Task>done=completedTasks();r.addView(sectionHeader("مكتمل",completedExpanded?"إخفاء":ar(done.size()),v->{completedExpanded=!completedExpanded;render();}));if(completedExpanded)for(Task t:done)if(matches(t))addTaskCard(r,t,false);List<Task>over=overdueTasks();r.addView(sectionHeader("متأخر",overdueExpanded?"إخفاء":ar(over.size()),v->{overdueExpanded=!overdueExpanded;render();}));if(overdueExpanded)for(Task t:over)if(matches(t))addTaskCard(r,t,false);if(shouldOfferRescue()&&!rescueActiveToday())addRescueCard(r);r.addView(sectionHeader("لاحقًا","التقاط فكرة",v->{tab="later";render();}));LinearLayout l=card();l.setPadding(dp(10),dp(8),dp(10),dp(8));add(r,l,3);l.addView(text("لا تفتح مسارًا جديدًا أثناء القرآن أو الطب. احفظ الفكرة هنا وعد إليها في الخميس أو مكافأة المشروع الجانبي.",9,MUTED,false));Button capture=smallButton("+ حفظ فكرة",PURPLE);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(38));cp.setMargins(0,dp(7),0,0);l.addView(capture,cp);capture.setOnClickListener(v->promptLater());if(!matchDateThisWeek().isEmpty()&&todayKey.equals(matchDateThisWeek()))addMatchCard(r);gap(r,18);return s;}

    private void addTaskCard(LinearLayout root,Task t,boolean compact){String st=status(t);LinearLayout box=card();box.setPadding(dp(9),compact?dp(7):dp(8),dp(9),compact?dp(7):dp(8));add(root,box,compact?5:6);LinearLayout rr=row();int c=colorFor(t.domain);rr.addView(new AppIconView(this,t.icon,c),new LinearLayout.LayoutParams(dp(39),dp(39)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(8),0,dp(5),0);tx.addView(text(t.title,compact?11:12,"done".equals(st)?MUTED:TEXT,true));LinearLayout meta=row();meta.addView(text(time(displayStart(t))+" • "+shortDomain(t.domain),8,MUTED,false),new LinearLayout.LayoutParams(0,-2,1));meta.addView(tierPill(t.tier));tx.addView(meta);if(!compact)tx.addView(text("يخدم: "+t.goal,7,c,false));rr.addView(tx,new LinearLayout.LayoutParams(0,-2,1));rr.addView(new StatusView(this,st),new LinearLayout.LayoutParams(dp(28),dp(28)));box.addView(rr);if(timerMatches(t)){TextView tm=center(timerLabel(),11,GREEN,true);tm.setPadding(0,dp(4),0,0);box.addView(tm);}box.setOnClickListener(v->showTaskDialog(t));}

    private void showTaskDialog(Task t){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);v.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);v.setPadding(dp(18),dp(8),dp(18),0);v.addView(text(t.title,16,TEXT,true));v.addView(text(time(displayStart(t))+" – "+time(displayEnd(t))+" • "+shortDomain(t.domain)+" • "+t.tier,9,MUTED,false));TextView why=text("الهدف: "+t.objective+"\nيخدم: "+t.goal,9,TEXT,false);why.setPadding(0,dp(9),0,dp(8));v.addView(why);if(timerMatches(t)){timerLiveText=center(timerLabel(),27,GREEN,true);v.addView(timerLiveText,new LinearLayout.LayoutParams(-1,dp(55)));handler.removeCallbacks(timerTick);handler.post(timerTick);}LinearLayout timerBtns=row();Button timer=smallButton(timerMatches(t)?(timerRunning()?"إيقاف مؤقت":"استئناف"):"ابدأ مؤقت",GREEN);Button end=smallButton("إنهاء المؤقت",MUTED);timerBtns.addView(timer,new LinearLayout.LayoutParams(0,dp(39),1));LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(0,dp(39),1);ep.setMargins(dp(5),0,0,0);timerBtns.addView(end,ep);v.addView(timerBtns);AlertDialog dialog=new AlertDialog.Builder(this).setView(v).setNegativeButton("إغلاق",null).setNeutralButton("تأجيل ١٥د",(d,w)->{prefs.edit().putInt("delay_"+todayKey+"_"+t.id,15).apply();render();}).setPositiveButton("خيارات الإنجاز",null).create();dialog.setOnShowListener(x->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(z->showStatusChoices(t,dialog));timer.setOnClickListener(z->{if(!timerMatches(t))startTimer(t,defaultFocusMinutes(t));else if(timerRunning())pauseTimer();else resumeTimer();dialog.dismiss();showTaskDialog(t);});end.setOnClickListener(z->{finishTimer(false);dialog.dismiss();render();});});dialog.setOnDismissListener(x->{timerLiveText=null;handler.removeCallbacks(timerTick);});dialog.show();}

    private void showStatusChoices(Task t,AlertDialog parent){String[] options={"مكتملة بالكامل","مكتملة جزئيًا","ألغيت لسبب مقبول","لم تبدأ / إعادة ضبط"};new AlertDialog.Builder(this).setTitle("حالة المهمة").setItems(options,(d,which)->{String st=which==0?"done":which==1?"partial":which==2?"cancelled":"none";parent.dismiss();changeStatus(t,st,true);}).show();}
    private void changeStatus(Task t,String newStatus,boolean askResult){String old=status(t);if(old.equals(newStatus))return;int oldScore=statusPoints(t,old),newScore=statusPoints(t,newStatus);SharedPreferences.Editor e=prefs.edit();e.putString(statusKey(todayKey,t.id),newStatus);e.putBoolean("reward_done_"+todayKey+"_"+t.id,"done".equals(newStatus));String dk="reward_day_points_"+todayKey,dom="reward_domain_"+t.domain;e.putInt(dk,Math.max(0,prefs.getInt(dk,0)+newScore-oldScore));e.putInt(dom,Math.max(0,prefs.getInt(dom,0)+newScore-oldScore));e.apply();if("done".equals(newStatus)||"partial".equals(newStatus)){getWindow().getDecorView().performHapticFeedback(HapticFeedbackConstants.CONFIRM);if(timerMatches(t))finishTimer(false);undoTaskId=t.id;undoOldStatus=old;undoUntil=System.currentTimeMillis()+5000;handler.postDelayed(()->{if(System.currentTimeMillis()>=undoUntil){undoTaskId=null;render();}},5100);if(askResult)showResultDialog(t);}syncCredits();render();}

    private void showResultDialog(Task t){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);v.setPadding(dp(18),dp(8),dp(18),0);List<EditText> fields=new ArrayList<>();List<String> names=new ArrayList<>();if(t.domain.equals("القرآن")){addResultField(v,fields,names,"عدد الصفحات","pages",true);addResultField(v,fields,names,"ماذا راجعت؟","topic",false);}else if(t.domain.equals("الطب والقبول")){addResultField(v,fields,names,"الموضوع","topic",false);addResultField(v,fields,names,"عدد الأسئلة","questions",true);addResultField(v,fields,names,"الإجابات الصحيحة","correct",true);}else if(t.domain.equals("الإنجليزية")){addResultField(v,fields,names,"كلمات جديدة","words",true);addResultField(v,fields,names,"دقائق الاستماع","listening",true);addResultField(v,fields,names,"ملاحظة قصيرة","note",false);}else if(t.domain.equals("العمل والدخل")){addResultField(v,fields,names,"ما المخرج الذي أنجزته؟","output",false);}else{addResultField(v,fields,names,"ملاحظة قصيرة (اختياري)","note",false);}new AlertDialog.Builder(this).setTitle("سجّل نتيجة المهمة").setView(v).setNegativeButton("تخطي",null).setPositiveButton("حفظ",(d,w)->{try{JSONObject o=new JSONObject();for(int i=0;i<fields.size();i++)o.put(names.get(i),fields.get(i).getText().toString().trim());o.put("focus_ms",focusMsFor(todayKey,t.id));prefs.edit().putString("result_"+todayKey+"_"+t.id,o.toString()).apply();}catch(Exception ignored){}render();}).show();}
    private void addResultField(LinearLayout v,List<EditText> fs,List<String> ns,String hint,String name,boolean numeric){EditText e=input(hint);if(numeric)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);v.addView(e,new LinearLayout.LayoutParams(-1,dp(48)));fs.add(e);ns.add(name);}

