    private void redeemReward(String title,int cost){if(isFriday(Calendar.getInstance())&&(title.contains("لعبة")||title.contains("أنمي"))){Toast.makeText(this,"الجمعة راحة أصلًا — لا تحتاج صرف رصيد لهذه المكافأة.",Toast.LENGTH_LONG).show();return;}if(prefs.getBoolean("reward_used_"+todayKey+"_"+title,false)){Toast.makeText(this,"استخدمت هذه المكافأة اليوم",Toast.LENGTH_SHORT).show();return;}if(credits()<cost){Toast.makeText(this,"الرصيد لا يكفي بعد",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("استخدام المكافأة").setMessage(title+"\nسيُخصم "+cost+" من رصيد المكافآت فقط، ولن تتأثر نقاط تقدمك.").setNegativeButton("إلغاء",null).setPositiveButton("استخدمها",(d,w)->{prefs.edit().putInt("reward_credits",credits()-cost).putBoolean("reward_used_"+todayKey+"_"+title,true).apply();render();}).show();}

