    private Task t(String id,int s,int e,String title,String domain,int pts,boolean req,String icon,String tier,String obj,String goal){return new Task(id,s,e,title,domain,pts,req,icon,tier,obj,goal);}
    private void addCustom(List<Task>a,Calendar d){try{JSONArray arr=new JSONArray(prefs.getString("custom_tasks","[]"));for(int i=0;i<arr.length();i++){JSONObject o=arr.optJSONObject(i);if(o==null||!o.optBoolean("active",true))continue;int dy=o.optInt("day",0);if(dy!=0&&dy!=d.get(Calendar.DAY_OF_WEEK))continue;a.add(t(o.optString("id","custom_"+i),o.optInt("start",960),o.optInt("end",990),o.optString("title","مهمة مخصصة"),o.optString("domain","الانضباط"),o.optInt("points",10),o.optBoolean("required",false),"check","مساند","مهمة أضفتها أنت","هدف شخصي"));}}catch(Exception ignored){}}

    private Task currentTask(){if(isFriday(Calendar.getInstance()))return null;String active=timerTaskId();if(active!=null){Task x=findTask(active);if(x!=null&&!isFinalStatus(status(x)))return x;}int now=nowMin();Task best=null;for(Task t:tasksToday()){if(isFinalStatus(status(t)))continue;int st=displayStart(t),en=displayEnd(t);if(now>=st&&now<=en)return t;if(st>=now&&(best==null||st<displayStart(best)))best=t;}return best;}
    private Task nextTaskAfter(Task cur){boolean hit=false;for(Task t:tasksToday()){if(isFinalStatus(status(t)))continue;if(hit)return t;if(t.id.equals(cur.id))hit=true;}return null;}
    private List<Task> nextTasks(int max){List<Task>a=new ArrayList<>();Task cur=currentTask();int now=nowMin();for(Task t:tasksToday()){if(cur!=null&&t.id.equals(cur.id))continue;if(isFinalStatus(status(t)))continue;if(displayStart(t)>=now||cur==null){a.add(t);if(a.size()>=max)break;}}return a;}
    private List<Task> laterTasks(){List<Task>a=new ArrayList<>();List<Task>skip=nextTasks(3);Task cur=currentTask();int now=nowMin();for(Task t:tasksToday()){if(cur!=null&&t.id.equals(cur.id))continue;if(skip.contains(t)||isFinalStatus(status(t)))continue;if(displayStart(t)>=now)a.add(t);}return a;}
    private List<Task> completedTasks(){List<Task>a=new ArrayList<>();for(Task t:tasksToday())if("done".equals(status(t))||"partial".equals(status(t)))a.add(t);return a;}
    private List<Task> overdueTasks(){List<Task>a=new ArrayList<>();int now=nowMin();for(Task t:tasksToday())if(!isFinalStatus(status(t))&&displayEnd(t)<now)a.add(t);return a;}
    private List<Task> homeTasks(){List<Task>a=new ArrayList<>();Task c=currentTask();if(c!=null)a.add(c);for(Task t:nextTasks(4))if(!a.contains(t))a.add(t);return a;}
    private boolean matches(Task t){if("الكل".equals(taskFilter))return true;if("أساسي".equals(taskFilter))return"أساسي".equals(t.tier);if("قرآن".equals(taskFilter))return t.domain.equals("القرآن");if("طب".equals(taskFilter))return t.domain.equals("الطب والقبول");if("إنجليزية".equals(taskFilter))return t.domain.equals("الإنجليزية");if("عمل".equals(taskFilter))return t.domain.equals("العمل والدخل");if("صحة".equals(taskFilter))return t.domain.equals("الصحة");if("أسرة".equals(taskFilter))return t.domain.equals("الأسرة");if("LeapAhead".equals(taskFilter))return t.id.startsWith("leap");return true;}

    private String statusKey(String date,String id){return"v17_status_"+date+"_"+id;}
    private String status(Task t){return statusOn(t,todayKey);}
    private String statusOn(Task t,String date){String s=prefs.getString(statusKey(date,t.id),"");if(!s.isEmpty())return s;if(prefs.getBoolean("reward_done_"+date+"_"+t.id,false))return"done";return"none";}
    private boolean isFinalStatus(String s){return"done".equals(s)||"partial".equals(s)||"cancelled".equals(s);}
    private int statusPoints(Task t,String st){if("done".equals(st))return t.points;if("partial".equals(st))return Math.max(1,t.points/2);return 0;}
    private boolean hasStatus(String id){Task t=findTask(id);return t!=null&&("done".equals(status(t))||"partial".equals(status(t)));}
    private Task findTask(String id){if(id==null)return null;for(Task t:tasksToday())if(t.id.equals(id))return t;return null;}
    private int displayStart(Task t){return t.start+prefs.getInt("delay_"+todayKey+"_"+t.id,0);}
    private int displayEnd(Task t){return t.end+prefs.getInt("delay_"+todayKey+"_"+t.id,0);}

    private boolean coreDone(String id){for(Task t:tasksToday())if((t.id.equals(id)||("quran".equals(id)&&(t.id.startsWith("quran")||t.id.contains("quran"))))&&("done".equals(status(t))||"partial".equals(status(t))))return true;return false;}
    private int coreDoneToday(){if(isFriday(Calendar.getInstance()))return 5;if(isThursday(Calendar.getInstance()))return thursdayCoreDone();int n=0;if(coreDone("quran"))n++;if(coreDone("medicine"))n++;if(coreDone("english"))n++;if(coreDone("work"))n++;if(coreDone("close"))n++;return n;}
    private int thursdayCoreDone(){int n=0;String[] ids={"thu_quran","thu_medicine","thu_english","thu_work","thu_review"};for(String id:ids)if(hasStatus(id))n++;return n;}

    private int dayPoints(Calendar c){return prefs.getInt("reward_day_points_"+dateKey(c),0);}
    private int dayTarget(Calendar c){if(isFriday(c))return 0;int n=0;for(Task t:tasksFor(c))if(t.required)n+=t.points;return n;}
    private int dayRate(Calendar c){if(isFriday(c))return 100;return pct(dayPoints(c),Math.max(1,dayTarget(c)));}
    private int weekRate(){return weekRateAt(0);}private int previousWeekRate(){return weekRateAt(1);}
    private int weekRateAt(int back){Calendar c=saturdayStart(Calendar.getInstance());c.add(Calendar.DAY_OF_MONTH,-7*back);Calendar end=(Calendar)c.clone();end.add(Calendar.DAY_OF_MONTH,5);if(back==0&&Calendar.getInstance().before(end))end=Calendar.getInstance();int p=0,t=0;while(!c.after(end)){if(!isFriday(c)){p+=dayPoints(c);t+=dayTarget(c);}c.add(Calendar.DAY_OF_MONTH,1);}return pct(p,Math.max(1,t));}
    private int monthRate(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int p=0,t=0;while(!c.after(now)){if(!isFriday(c)){p+=dayPoints(c);t+=dayTarget(c);}c.add(Calendar.DAY_OF_MONTH,1);}return pct(p,Math.max(1,t));}
    private int yearRate(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.MONTH,Calendar.JANUARY);c.set(Calendar.DAY_OF_MONTH,1);int p=0,t=0;while(!c.after(now)){if(!isFriday(c)){p+=dayPoints(c);t+=dayTarget(c);}c.add(Calendar.DAY_OF_MONTH,1);}return pct(p,Math.max(1,t));}
    private int monthCompleted(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){String dk=dateKey(c);for(Task t:tasksFor(c))if("done".equals(statusOn(t,dk)))n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int monthTaskCount(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){n+=tasksFor(c).size();c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int monthDoneDomain(String domain){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){String dk=dateKey(c);for(Task t:tasksFor(c))if(t.domain.equals(domain)&&("done".equals(statusOn(t,dk))||"partial".equals(statusOn(t,dk))))n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int quranPagesMonth(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){String dk=dateKey(c);for(Task t:tasksFor(c))if(t.domain.equals("القرآن")&&("done".equals(statusOn(t,dk))||"partial".equals(statusOn(t,dk)))){int p=resultInt(dk,t.id,"pages");n+=p>0?p:(t.id.equals("thu_quran")?6:2);}c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int monthEnglishMinutes(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);int n=0;while(!c.after(now)){String dk=dateKey(c);for(Task t:tasksFor(c))if(t.domain.equals("الإنجليزية"))n+=resultInt(dk,t.id,"listening");c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int resultInt(String date,String id,String key){try{JSONObject o=new JSONObject(prefs.getString("result_"+date+"_"+id,"{}"));String s=o.optString(key,"0").replaceAll("[^0-9]","");return s.isEmpty()?0:Integer.parseInt(s);}catch(Exception e){return 0;}}
    private long focusMsFor(String date,String id){return prefs.getLong("focus_ms_"+date+"_"+id,0);}
    private long focusMsMonth(){Calendar c=Calendar.getInstance(),now=Calendar.getInstance();c.set(Calendar.DAY_OF_MONTH,1);long n=0;while(!c.after(now)){String dk=dateKey(c);for(Task t:tasksFor(c))n+=focusMsFor(dk,t.id);c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private long focusMsWeek(){Calendar c=saturdayStart(Calendar.getInstance()),now=Calendar.getInstance();long n=0;while(!c.after(now)&&c.get(Calendar.DAY_OF_WEEK)!=Calendar.FRIDAY){String dk=dateKey(c);for(Task t:tasksFor(c))n+=focusMsFor(dk,t.id);c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int strongDaysThisWeek(){Calendar c=saturdayStart(Calendar.getInstance()),now=Calendar.getInstance();int n=0;while(!c.after(now)){if(!isFriday(c)&&dayRate(c)>=80)n++;c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int streak(){Calendar c=Calendar.getInstance();if(isFriday(c))c.add(Calendar.DAY_OF_MONTH,-1);else if(dayRate(c)<80)c.add(Calendar.DAY_OF_MONTH,-1);int n=0,guard=0;while(guard++<365){if(isFriday(c)){c.add(Calendar.DAY_OF_MONTH,-1);continue;}if(dayRate(c)>=80){n++;c.add(Calendar.DAY_OF_MONTH,-1);}else break;}return n;}
    private int quickComebacks(){Calendar c=Calendar.getInstance();c.add(Calendar.DAY_OF_MONTH,-60);Calendar now=Calendar.getInstance();int n=0;boolean weak=false;while(!c.after(now)){if(isFriday(c)){c.add(Calendar.DAY_OF_MONTH,1);continue;}int r=dayRate(c);if(weak&&r>=80){n++;weak=false;}else weak=r<50;c.add(Calendar.DAY_OF_MONTH,1);}return n;}
    private int weekDomainRate(String d){Calendar c=saturdayStart(Calendar.getInstance()),now=Calendar.getInstance();int earned=0,target=0;while(!c.after(now)){String dk=dateKey(c);for(Task t:tasksFor(c))if(t.domain.equals(d)){if(t.required)target+=t.points;earned+=statusPoints(t,statusOn(t,dk));}c.add(Calendar.DAY_OF_MONTH,1);}return target==0?0:pct(earned,target);}
    private String strongestDomain(){String best="القرآن";int v=-1;for(String d:domainColors.keySet())if(!d.equals("الراحة")&&!d.equals("الدين والمسجد")){int x=weekDomainRate(d);if(x>v){v=x;best=d;}}return best;}
    private String weakestDomain(){String best="العمل والدخل";int v=101;for(String d:domainColors.keySet())if(!d.equals("الراحة")&&!d.equals("الدين والمسجد")){int x=weekDomainRate(d);if(x<v){v=x;best=d;}}return best;}
    private String strongestDomainMonth(){return strongestDomain();}private String weakestDomainMonth(){return weakestDomain();}
    private int countDoneIds(String contains){int n=0;for(Map.Entry<String,?>e:prefs.getAll().entrySet())if((e.getKey().startsWith("v17_status_")&&e.getKey().contains(contains)&&"done".equals(String.valueOf(e.getValue())))||(e.getKey().startsWith("reward_done_")&&e.getKey().contains(contains)&&Boolean.TRUE.equals(e.getValue())))n++;return n;}
    private int countDoneDomainAll(String domain){return domainPoints(domain)/8;}

    private int domainPoints(String d){return prefs.getInt("reward_domain_"+d,0);}private int totalPoints(){int n=0;for(String d:domainColors.keySet())n+=domainPoints(d);return n;}private int credits(){return prefs.getInt("reward_credits",0);}
    private void syncCredits(){if(isFriday(Calendar.getInstance()))return;SharedPreferences.Editor e=prefs.edit();int add=0;String dk=todayKey;if(coreDoneToday()>=4&&!prefs.getBoolean("credit_core4_"+dk,false)){add+=5;e.putBoolean("credit_core4_"+dk,true);}if(coreDoneToday()==5&&!prefs.getBoolean("credit_core5_"+dk,false)){add+=3;e.putBoolean("credit_core5_"+dk,true);}String wk=weekId(Calendar.getInstance());if(strongDaysThisWeek()>=5&&!prefs.getBoolean("credit_week5_"+wk,false)){add+=20;e.putBoolean("credit_week5_"+wk,true);}add+=awardOnce(e,"credit_v17_quran30",countDoneIds("quran")>=30,25);add+=awardOnce(e,"credit_v17_medicine30",countDoneIds("medicine")>=30,30);if(add>0)e.putInt("reward_credits",credits()+add);e.apply();}
    private int awardOnce(SharedPreferences.Editor e,String key,boolean ok,int amount){if(ok&&!prefs.getBoolean(key,false)){e.putBoolean(key,true);return amount;}return 0;}

    private void startTimer(Task t,int min){finishTimer(false);long now=System.currentTimeMillis(),duration=min*60000L;prefs.edit().putString("timer_task_"+todayKey,t.id).putLong("timer_remaining_"+todayKey,duration).putLong("timer_last_start_"+todayKey,now).putBoolean("timer_running_"+todayKey,true).apply();}
    private boolean timerRunning(){return prefs.getBoolean("timer_running_"+todayKey,false)&&timerTaskId()!=null;}
    private String timerTaskId(){String x=prefs.getString("timer_task_"+todayKey,"");return x.isEmpty()?null:x;}
    private boolean timerMatches(Task t){return t!=null&&t.id.equals(timerTaskId());}
    private long timerRemainingMs(){long rem=prefs.getLong("timer_remaining_"+todayKey,0);if(timerRunning())rem-=Math.max(0,System.currentTimeMillis()-prefs.getLong("timer_last_start_"+todayKey,System.currentTimeMillis()));return Math.max(0,rem);}
    private String timerLabel(){long sec=timerRemainingMs()/1000;return two((int)(sec/60))+":"+two((int)(sec%60));}
    private void pauseTimer(){if(!timerRunning())return;long now=System.currentTimeMillis(),last=prefs.getLong("timer_last_start_"+todayKey,now),elapsed=Math.max(0,now-last),rem=Math.max(0,prefs.getLong("timer_remaining_"+todayKey,0)-elapsed);String id=timerTaskId();addFocus(id,elapsed);prefs.edit().putLong("timer_remaining_"+todayKey,rem).putBoolean("timer_running_"+todayKey,false).apply();}
    private void resumeTimer(){if(timerTaskId()==null)return;prefs.edit().putLong("timer_last_start_"+todayKey,System.currentTimeMillis()).putBoolean("timer_running_"+todayKey,true).apply();}
    private void finishTimer(boolean complete){String id=timerTaskId();if(id==null)return;if(timerRunning()){long now=System.currentTimeMillis(),last=prefs.getLong("timer_last_start_"+todayKey,now);addFocus(id,Math.max(0,now-last));}SharedPreferences.Editor e=prefs.edit();e.remove("timer_task_"+todayKey).remove("timer_remaining_"+todayKey).remove("timer_last_start_"+todayKey).putBoolean("timer_running_"+todayKey,false).apply();if(complete){Task t=findTask(id);if(t!=null)changeStatus(t,"done",true);}}
    private void addFocus(String id,long ms){if(id==null||ms<=0)return;String k="focus_ms_"+todayKey+"_"+id;prefs.edit().putLong(k,prefs.getLong(k,0)+ms).apply();}
    private int defaultFocusMinutes(Task t){int m=Math.max(15,Math.min(60,t.end-t.start));return m;}
    private String two(int n){return n<10?"0"+n:String.valueOf(n);}

    private boolean shouldOfferRescue(){if(isThursday(Calendar.getInstance())||isFriday(Calendar.getInstance())||!emergencyFor(Calendar.getInstance()).isEmpty())return false;return nowMin()>=960&&dayRate(Calendar.getInstance())<35&&overdueTasks().size()>=3;}
    private boolean rescueActiveToday(){return prefs.getBoolean("rescue_"+todayKey,false);}
    private String emergencyFor(Calendar c){return prefs.getString("emergency_"+dateKey(c),"");}
    private String dayMode(Calendar c){if(isFriday(c))return"friday";if(isThursday(c))return"thursday";if(dateKey(c).equals(todayKey)&&rescueActiveToday())return"rescue";if(!emergencyFor(c).isEmpty())return"emergency";return"normal";}
    private boolean matchUsedOn(Calendar d){return dateKey(d).equals(prefs.getString("match_week_"+weekId(d),""));}
    private String matchDateThisWeek(){return prefs.getString("match_week_"+weekId(Calendar.getInstance()),"");}

    private void addUndoBar(LinearLayout r){LinearLayout b=new LinearLayout(this);b.setGravity(Gravity.CENTER_VERTICAL);b.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);b.setPadding(dp(10),dp(7),dp(10),dp(7));b.setBackground(round(NAVY,13));TextView t=text("تم تحديث المهمة",9,Color.WHITE,true);b.addView(t,new LinearLayout.LayoutParams(0,-2,1));TextView u=pill("تراجع",GREEN2);b.addView(u);add(r,b,7);u.setOnClickListener(v->{Task x=findTask(undoTaskId);if(x!=null){String current=status(x);int oldPts=statusPoints(x,current),newPts=statusPoints(x,undoOldStatus);prefs.edit().putString(statusKey(todayKey,x.id),undoOldStatus).putBoolean("reward_done_"+todayKey+"_"+x.id,"done".equals(undoOldStatus)).putInt("reward_day_points_"+todayKey,Math.max(0,prefs.getInt("reward_day_points_"+todayKey,0)+newPts-oldPts)).putInt("reward_domain_"+x.domain,Math.max(0,domainPoints(x.domain)+newPts-oldPts)).apply();}undoTaskId=null;render();});}

