    private int levelFor(int p){if(p>=8000)return 6;if(p>=5000)return 5;if(p>=3000)return 4;if(p>=1500)return 3;if(p>=600)return 2;return 1;}private int levelBase(int l){switch(l){case 2:return 600;case 3:return 1500;case 4:return 3000;case 5:return 5000;case 6:return 8000;default:return 0;}}private int levelNext(int l){switch(l){case 1:return 600;case 2:return 1500;case 3:return 3000;case 4:return 5000;case 5:return 8000;default:return 10000;}}private String levelName(int l){switch(l){case 2:return"منتظم";case 3:return"متقدم";case 4:return"راسخ";case 5:return"متقن";case 6:return"متمكن";default:return"البداية";}}private String levelMessage(int l){switch(l){case 1:return"ثبت الأساس قبل زيادة الحمل.";case 2:return"الاستمرار أهم من الكثرة.";case 3:return"تقدمك صار قابلًا للقياس.";case 4:return"العادة بدأت تصبح راسخة.";case 5:return"جودة التنفيذ أهم من عدد المهام.";default:return"حافظ على الاتزان ولا تطارد النقاط.";}}
    private String rankFor(int p){if(p>=1200)return"متمكن";if(p>=650)return"ذهبي";if(p>=300)return"فضي";return"برونزي";}private int rankBase(int p){if(p>=1200)return 1200;if(p>=650)return 650;if(p>=300)return 300;return 0;}private int rankNext(int p){if(p>=1200)return 1800;if(p>=650)return 1200;if(p>=300)return 650;return 300;}

    private int colorFor(String d){Integer c=domainColors.get(d);return c==null?GREEN:c;}private String shortDomain(String d){if(d.equals("الطب والقبول"))return"الطب";if(d.equals("العمل والدخل"))return"العمل";if(d.equals("المعرفة والقراءة"))return"القراءة";if(d.equals("الدين والمسجد"))return"المسجد";return d;}private String iconForDomain(String d){if(d.equals("القرآن"))return"quran";if(d.equals("الطب والقبول"))return"medicine";if(d.equals("الإنجليزية"))return"headphones";if(d.equals("العمل والدخل"))return"briefcase";if(d.equals("الصحة"))return"heart";if(d.equals("المعرفة والقراءة"))return"book";if(d.equals("التواصل"))return"talk";if(d.equals("الأسرة"))return"family";if(d.equals("الدين والمسجد"))return"mosque";return"star";}
    private int nowMin(){Calendar c=Calendar.getInstance();return c.get(Calendar.HOUR_OF_DAY)*60+c.get(Calendar.MINUTE);}private int pct(int a,int b){return b<=0?0:Math.max(0,Math.min(100,Math.round(a*100f/b)));}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}private int withAlpha(int c,int a){return Color.argb(a,Color.red(c),Color.green(c),Color.blue(c));}
    private String dateKey(Calendar c){return new SimpleDateFormat("yyyyMMdd",Locale.US).format(c.getTime());}private String monthId(Calendar c){return new SimpleDateFormat("yyyyMM",Locale.US).format(c.getTime());}private String weekId(Calendar c){Calendar s=saturdayStart(c);return dateKey(s);}private Calendar saturdayStart(Calendar n){Calendar c=(Calendar)n.clone();while(c.get(Calendar.DAY_OF_WEEK)!=Calendar.SATURDAY)c.add(Calendar.DAY_OF_MONTH,-1);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c;}private boolean isThursday(Calendar c){return c.get(Calendar.DAY_OF_WEEK)==Calendar.THURSDAY;}private boolean isFriday(Calendar c){return c.get(Calendar.DAY_OF_WEEK)==Calendar.FRIDAY;}private String time(int min){int h=(min/60)%24,m=min%60;String suf=h>=12?"م":"ص";int hh=h%12;if(hh==0)hh=12;return ar(hh)+":"+(m<10?"٠":"")+ar(m)+" "+suf;}private String formatMinutes(int min){if(min<60)return ar(min)+" د";return ar(min/60)+"س"+(min%60>0?" "+ar(min%60)+"د":"");}private String ar(int n){String s=String.valueOf(n),en="0123456789",aa="٠١٢٣٤٥٦٧٨٩";for(int i=0;i<10;i++)s=s.replace(en.charAt(i),aa.charAt(i));return s;}private String dayNameFromKey(String key){try{Calendar c=Calendar.getInstance();c.setTime(new SimpleDateFormat("yyyyMMdd",Locale.US).parse(key));String[] names={"الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"};return names[c.get(Calendar.DAY_OF_WEEK)-1];}catch(Exception e){return"—";}}

